-- ============================================
-- LUMA — Thème 5 : MOYEN 2/3 x4 — Expliquer une allergie médicamenteuse
-- ============================================


update scenarios set content = '{"characters": {"nurse": "l''infirmière", "doctor": "le médecin"}, "start_node": "n1", "nodes": {"n1": {"speaker": "nurse", "text": "Before your procedure, I need to go over your medical information. Any known allergies?", "text_fr": "Avant votre intervention, je dois passer en revue vos informations médicales. Des allergies connues ?", "choices": [{"text": "Yes, I''m allergic to penicillin — it''s quite important.", "text_fr": "Oui, je suis allergique à la pénicilline — c''est assez important.", "next": "n2"}, {"text": "I believe I might have a reaction to certain antibiotics, though I''m not 100% sure.", "text_fr": "Je pense avoir une réaction à certains antibiotiques, même si je ne suis pas sûr à 100%.", "next": "n2b"}]}, "n2": {"speaker": "nurse", "text": "Thank you for letting me know. Can you describe what happens when you''re exposed to it?", "text_fr": "Merci de me le signaler. Vous pouvez décrire ce qui se passe quand vous y êtes exposé ?", "choices": [{"text": "I break out in hives and my throat feels tight.", "text_fr": "J''ai des plaques d''urticaire et ma gorge se serre.", "next": "n3"}, {"text": "I get a severe rash all over my body.", "text_fr": "J''ai une éruption cutanée sévère sur tout le corps.", "next": "n3"}]}, "n2b": {"speaker": "nurse", "text": "That''s important to flag. Do you remember which antibiotic caused the reaction?", "text_fr": "C''est important à signaler. Vous vous souvenez de quel antibiotique a causé la réaction ?", "choices": [{"text": "I think it was amoxicillin, when I was a child.", "text_fr": "Je pense que c''était l''amoxicilline, quand j''étais enfant.", "next": "n3"}, {"text": "I''m honestly not sure, but my mother mentioned it once.", "text_fr": "Honnêtement pas sûr, mais ma mère l''a mentionné une fois.", "next": "n3"}]}, "n3": {"speaker": "nurse", "text": "That sounds like it could be serious. I''ll flag this clearly in your file right away.", "text_fr": "Ça semble pouvoir être sérieux. Je vais signaler ça clairement dans votre dossier tout de suite.", "choices": [{"text": "Thank you, I really don''t want any mix-ups today.", "text_fr": "Merci, je ne veux vraiment aucune confusion aujourd''hui.", "next": "n4"}]}, "n4": {"speaker": "nurse", "text": "Absolutely, patient safety is our priority. I''ll also inform the doctor directly.", "text_fr": "Absolument, la sécurité du patient est notre priorité. J''informe aussi le médecin directement.", "choices": [{"text": "I appreciate that, thank you for being thorough.", "text_fr": "J''apprécie, merci d''être minutieuse.", "next": "n5"}]}, "n5": {"speaker": "doctor", "text": "I understand you have a penicillin allergy — thank you for flagging that clearly.", "text_fr": "Je comprends que vous avez une allergie à la pénicilline — merci de l''avoir signalé clairement.", "choices": [{"text": "Yes, it''s a pretty severe reaction, so I wanted to be sure it was noted.", "text_fr": "Oui, c''est une réaction assez sévère, donc je voulais être sûr que ce soit noté.", "next": "n6"}, {"text": "Yes, I just want to make sure it doesn''t get overlooked.", "text_fr": "Oui, je veux juste m''assurer que ça ne soit pas oublié.", "next": "n6"}]}, "n6": {"speaker": "doctor", "text": "We''ll use an alternative antibiotic if needed during your procedure, no penicillin-based drugs.", "text_fr": "On utilisera un antibiotique alternatif si nécessaire pendant votre intervention, aucun médicament à base de pénicilline.", "choices": [{"text": "That''s a relief to hear, thank you.", "text_fr": "Ça soulage d''entendre ça, merci.", "next": "n7"}, {"text": "Perfect, I feel much more at ease now.", "text_fr": "Parfait, je me sens beaucoup plus rassuré maintenant.", "next": "n7"}]}, "n7": {"speaker": "doctor", "text": "Of course. Is there anything else about your medical history I should know before we proceed?", "text_fr": "Bien sûr. Autre chose sur vos antécédents médicaux que je devrais savoir avant qu''on procède ?", "choices": [{"text": "No, that''s the main thing — I just wanted to be thorough.", "text_fr": "Non, c''est le principal — je voulais juste être minutieux.", "next": "n8"}, {"text": "Actually, I also react badly to certain anesthetics, if that matters.", "text_fr": "En fait, je réagis mal à certains anesthésiques aussi, si ça compte.", "next": "n8b"}]}, "n8": {"speaker": "doctor", "text": "Perfect, we have everything we need. We''ll proceed safely and carefully.", "text_fr": "Parfait, on a tout ce dont on a besoin. On va procéder en toute sécurité et avec soin.", "choices": [{"text": "Thank you, I feel confident about this now.", "text_fr": "Merci, je me sens confiant maintenant.", "next": "end_safe"}]}, "n8b": {"speaker": "doctor", "text": "That''s very important — thank you for mentioning it, we''ll adjust our approach accordingly.", "text_fr": "C''est très important — merci de l''avoir mentionné, on va ajuster notre approche en conséquence.", "choices": [{"text": "I appreciate you taking this so seriously.", "text_fr": "J''apprécie que vous preniez ça si au sérieux.", "next": "end_safe"}]}, "end_safe": {"speaker": "doctor", "text": "Your safety is our top priority. We''re ready to begin whenever you are.", "text_fr": "Votre sécurité est notre priorité absolue. On est prêts à commencer quand vous voulez.", "end": true, "ending_label": "Allergie signalée avec précision et sérieux 💊✅"}}}'::jsonb, is_playable = true
where title = 'Expliquer une allergie médicamenteuse'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));
